                duplicates++;
                errors.add(new FrameCsvImportError(rowNumber, frameId, exception.getMessage()));
            } catch (RowImportException exception) {
                failed++;
                errors.add(new FrameCsvImportError(rowNumber, frameId, exception.getMessage()));
