import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import {
  FrameApiError,
  getFrames,
  type FrameFilters as FilterValues,
  type FramePage,
  type GetFramesParams,
} from '../api/frames'
import { FrameFilters } from './FrameFilters'
import { FrameTable } from './FrameTable'
import { Pagination } from './Pagination'

const EMPTY_FILTERS: FilterValues = { status: '', mediaType: '', environment: '', format: '', region: '' }
const INITIAL_REQUEST: ActiveRequest = {
  id: 0,
  params: { ...EMPTY_FILTERS, page: 0, size: 20, q: '' },
}

type ActiveRequest = { id: number; params: GetFramesParams }
type RequestUpdate = (current: GetFramesParams) => GetFramesParams
type Props = {
  successMessage: string | null
  focusOnMount: boolean
  onNew: () => void
  onImport: () => void
  onView: (frameId: string) => void
  onEdit: (frameId: string) => void
}

export function InventoryPage({ successMessage, focusOnMount, onNew, onImport, onView, onEdit }: Props) {
  const headingRef = useRef<HTMLHeadingElement>(null)
  const [queryInput, setQueryInput] = useState('')
  const [filters, setFilters] = useState<FilterValues>(EMPTY_FILTERS)
  const requestSequence = useRef(0)
  const requestRef = useRef<ActiveRequest>(INITIAL_REQUEST)
  const activeRequestId = useRef(INITIAL_REQUEST.id)
  const [request, setRequest] = useState<ActiveRequest>(INITIAL_REQUEST)
  const [settledRequestId, setSettledRequestId] = useState<number | null>(null)
  const [result, setResult] = useState<FramePage | null>(null)
  const [error, setError] = useState<string | null>(null)
  const loading = settledRequestId !== request.id
  const visibleError = settledRequestId === request.id ? error : null

  useEffect(() => {
    if (focusOnMount) headingRef.current?.focus()
  }, [focusOnMount])
  const filterSuggestions = useMemo(() => {
    const frames = result?.items ?? []
    return {
      mediaType: uniqueValues(frames.map((frame) => frame.mediaType)),
      environment: uniqueValues(frames.map((frame) => frame.environment)),
      format: uniqueValues(frames.map((frame) => frame.format)),
      region: uniqueValues(frames.map((frame) => frame.region)),
    }
  }, [result])

  const scheduleRequest = useCallback((update: RequestUpdate, force = false) => {
    const current = requestRef.current
    const params = update(current.params)
    if (!force && params === current.params) return

    const next = { id: ++requestSequence.current, params }
    requestRef.current = next
    activeRequestId.current = next.id
    setRequest(next)
  }, [])

  useEffect(() => {
    const timeout = window.setTimeout(() => {
      const q = queryInput.trim()

      scheduleRequest((current) => {
        return current.q === q ? current : { ...current, q, page: 0 }
      })
    }, 300)
    return () => window.clearTimeout(timeout)
  }, [queryInput, scheduleRequest])

  useEffect(() => {
    const controller = new AbortController()
    getFrames(request.params, controller.signal)
      .then((data) => {
        if (activeRequestId.current !== request.id) return
        if (request.params.page > 0 && request.params.page >= data.totalPages) {
          const correctedPage = Math.max(0, data.totalPages - 1)
          scheduleRequest((current) => ({ ...current, page: correctedPage }))
          return
        }
        setResult(data)
        setError(null)
        setSettledRequestId(request.id)
      })
      .catch((caught: unknown) => {
        if (caught instanceof DOMException && caught.name === 'AbortError') return
        if (activeRequestId.current !== request.id) return
        setError(caught instanceof FrameApiError || caught instanceof Error ? caught.message : 'An unexpected error occurred.')
        setSettledRequestId(request.id)
      })
    return () => controller.abort()
  }, [request, scheduleRequest])

  const hasActiveFilters = Boolean(
    request.params.q || request.params.status || request.params.mediaType || request.params.environment ||
    request.params.format || request.params.region,
  )
  const changeFilter = <K extends keyof FilterValues,>(name: K, value: FilterValues[K]) => {
    setFilters((current) => ({ ...current, [name]: value }))
    if (name === 'status') {
      const status = value as FilterValues['status']
      scheduleRequest((current) => current.status === status ? current : { ...current, status, page: 0 })
      return
    }

    const suggestionName = name as Exclude<keyof FilterValues, 'status'>
    const normalizedValue = value.trim()
    scheduleRequest((current) => current[suggestionName] === normalizedValue
      ? current
      : { ...current, [suggestionName]: normalizedValue, page: 0 })
  }
  const clearFilters = () => {
    setQueryInput('')
    setFilters(EMPTY_FILTERS)
    scheduleRequest((current) => {
      const unchanged = current.q === '' && current.status === '' && current.mediaType === '' &&
        current.environment === '' && current.format === '' && current.region === ''
      return unchanged ? current : { ...current, ...EMPTY_FILTERS, q: '', page: 0 }
    })
  }
  const changeSize = (nextSize: number) => {
    scheduleRequest((current) => current.size === nextSize ? current : { ...current, size: nextSize, page: 0 })
  }
  const changePage = (nextPage: number) => {
    scheduleRequest((current) => current.page === nextPage ? current : { ...current, page: nextPage })
  }
  const retry = () => {
    scheduleRequest((current) => current, true)
  }

  return (
    <>
      <header className="page-header"><div>
          <h1 ref={headingRef} tabIndex={-1}>Frames</h1>
          <p className="page-meta">{result && !visibleError ? `${result.totalElements.toLocaleString()} frames` : 'Search the frame inventory'}</p>
        </div>
        <div className="page-header-actions">
          <button className="button" type="button" onClick={onImport}><UploadIcon /> Import CSV</button>
          <button className="button button-primary" type="button" onClick={onNew}><PlusIcon /> New frame</button>
        </div>
      </header>
      {successMessage && <div className="success-message" role="status"><CheckIcon /> {successMessage}</div>}
      <div className="inventory-layout">
        <FrameFilters query={queryInput} filters={filters} suggestions={filterSuggestions} onQueryChange={setQueryInput}
          onFilterChange={changeFilter} onClear={clearFilters} />
        <section className="results" aria-label="Frame results" aria-busy={loading}>
          <div className="surface">
            {loading && (!result || result.items.length === 0) ? <LoadingState /> : visibleError ? (
              <ErrorState message={visibleError} onRetry={retry} />
            ) : result && result.items.length === 0 ? (
              <EmptyState hasActiveFilters={hasActiveFilters} onClear={clearFilters} />
            ) : result ? <>
              {loading && <div className="results-loading" role="status">
                <span className="loading-spinner loading-spinner-small" /> Updating frames
              </div>}
              <FrameTable frames={result.items} onView={onView} onEdit={onEdit} />
              <Pagination page={result.page} size={result.size} totalElements={result.totalElements}
                totalPages={result.totalPages} disabled={loading} onPageChange={changePage} onSizeChange={changeSize} />
            </> : null}
          </div>
        </section>
      </div>
    </>
  )
}

function uniqueValues(values: Array<string | null>) {
  return [...new Set(values.flatMap((value) => value?.trim() ? [value.trim()] : []))]
    .sort((left, right) => left.localeCompare(right))
}

function LoadingState() {
  return <div className="state-panel" role="status"><div className="state-panel-content">
    <span className="state-icon"><span className="loading-spinner" /></span><h2>Loading frames</h2>
    <p>Fetching the latest inventory.</p>
  </div></div>
}

function ErrorState({ message, onRetry }: { message: string; onRetry: () => void }) {
  return <div className="state-panel" role="alert"><div className="state-panel-content">
    <span className="state-icon"><AlertIcon /></span><h2>Could not load frames</h2><p>{message}</p>
    <button className="button button-primary" type="button" onClick={onRetry}>Try again</button>
  </div></div>
}

function EmptyState({ hasActiveFilters, onClear }: { hasActiveFilters: boolean; onClear: () => void }) {
  return <div className="state-panel"><div className="state-panel-content">
    <span className="state-icon"><SearchIcon /></span>
    <h2>{hasActiveFilters ? 'No matching frames' : 'No frames found'}</h2>
    <p>{hasActiveFilters ? 'Try changing your search or clearing the filters.' : 'The inventory does not contain any frames yet.'}</p>
    {hasActiveFilters && <button className="button" type="button" onClick={onClear}>Clear filters</button>}
  </div></div>
}

function SearchIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <circle cx="11" cy="11" r="7" /><path d="m20 20-3.5-3.5" />
  </svg>
}

function AlertIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <circle cx="12" cy="12" r="9" /><path d="M12 8v5M12 16h.01" />
  </svg>
}

function PlusIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <path d="M12 5v14M5 12h14" />
  </svg>
}

function UploadIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <path d="M12 16V4m0 0L7 9m5-5 5 5M5 14v5h14v-5" />
  </svg>
}

function CheckIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <path d="m5 12 4 4L19 6" />
  </svg>
}

import type { FrameFilters as FrameFilterValues } from '../api/frames'

type FilterSuggestions = {
  [K in Exclude<keyof FrameFilterValues, 'status'>]: string[]
}

type Props = {
  query: string
  filters: FrameFilterValues
  suggestions: FilterSuggestions
  onQueryChange: (value: string) => void
  onFilterChange: <K extends keyof FrameFilterValues>(name: K, value: FrameFilterValues[K]) => void
  onClear: () => void
}

export function FrameFilters({ query, filters, suggestions, onQueryChange, onFilterChange, onClear }: Props) {
  const hasFilters = Boolean(
    query.trim() || filters.status || filters.mediaType.trim() ||
    filters.environment.trim() || filters.format.trim() || filters.region.trim(),
  )

  return (
    <aside className="filters" aria-label="Frame filters">
      <div className="filters-header">
        <h2>Filter frames</h2>
      </div>
      <div className="filter-search">
        <div className="field">
          <label htmlFor="frame-search">Search</label>
          <input id="frame-search" className="input search-input" type="search" value={query}
            placeholder="ID, site or location" onChange={(event) => onQueryChange(event.target.value)} />
        </div>
      </div>
      <div className="filter-controls">
        <div className="field">
          <label htmlFor="status-filter">Status</label>
          <select id="status-filter" className="select" value={filters.status}
            onChange={(event) => onFilterChange('status', event.target.value as FrameFilterValues['status'])}>
            <option value="">All</option><option value="LIVE">LIVE</option><option value="INACTIVE">INACTIVE</option>
          </select>
        </div>
        <StringFilter id="media-type-filter" label="Media type" value={filters.mediaType}
          suggestions={suggestions.mediaType}
          onChange={(value) => onFilterChange('mediaType', value)} />
        <StringFilter id="environment-filter" label="Environment" value={filters.environment}
          suggestions={suggestions.environment}
          onChange={(value) => onFilterChange('environment', value)} />
        <StringFilter id="format-filter" label="Format" value={filters.format}
          suggestions={suggestions.format}
          onChange={(value) => onFilterChange('format', value)} />
        <StringFilter id="region-filter" label="Region" value={filters.region}
          suggestions={suggestions.region}
          onChange={(value) => onFilterChange('region', value)} />
        {hasFilters && <button className="button button-link clear-filters" type="button" onClick={onClear}>Clear all</button>}
      </div>
    </aside>
  )
}

function StringFilter({ id, label, value, suggestions, onChange }: {
  id: string; label: string; value: string; suggestions: string[]; onChange: (value: string) => void
}) {
  const suggestionListId = `${id}-suggestions`

  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      <input id={id} className="input" type="text" list={suggestionListId} value={value} placeholder="All"
        onChange={(event) => onChange(event.target.value)} />
      <datalist id={suggestionListId}>
        {suggestions.map((suggestion) => <option key={suggestion} value={suggestion} />)}
      </datalist>
    </div>
  )
}

import { useRef, useState, type FormEvent, type ReactNode } from 'react'
import {
  type FormErrors,
  type FormField,
  type FrameFormValues,
  validateFrameForm,
} from './frameFormModel'
import { COUNTRY_OPTIONS } from './countries'

type Props = {
  mode: 'create' | 'edit'
  initialValues: FrameFormValues
  submitting: boolean
  submitError: string | null
  serverErrors: FormErrors
  onSubmit: (values: FrameFormValues) => void
  onCancel: () => void
  onValueChange: () => void
}

export function FrameForm({
  mode, initialValues, submitting, submitError, serverErrors, onSubmit, onCancel, onValueChange,
}: Props) {
  const [values, setValues] = useState(initialValues)
  const [clientErrors, setClientErrors] = useState<FormErrors>({})
  const errorSummaryRef = useRef<HTMLDivElement>(null)
  const errors = { ...serverErrors, ...clientErrors }

  const changeValue = (field: FormField, value: string) => {
    setValues((current) => ({ ...current, [field]: value }))
    setClientErrors((current) => removeError(current, field))
    onValueChange()
  }

  const validateField = (field: FormField) => {
    const nextError = validateFrameForm(values, mode)[field]
    setClientErrors((current) => nextError
      ? { ...current, [field]: nextError }
      : removeError(current, field))
  }

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (submitting) return
    const nextErrors = validateFrameForm(values, mode)
    setClientErrors(nextErrors)
    if (Object.keys(nextErrors).length > 0) {
      window.requestAnimationFrame(() => errorSummaryRef.current?.focus())
      return
    }
    onSubmit(values)
  }

  const fieldProps = (field: FormField) => ({
    field,
    value: values[field],
    error: errors[field],
    onChange: changeValue,
    onBlur: validateField,
  })

  return (
    <form className="frame-form" noValidate onSubmit={submit} aria-busy={submitting}>
      {(submitError || Object.keys(clientErrors).length > 0) && (
        <div className="form-error-summary" role="alert" tabIndex={-1} ref={errorSummaryRef}>
          <strong>{Object.keys(clientErrors).length > 0 ? 'Check the highlighted fields.' : 'Could not save frame.'}</strong>
          {submitError && <span>{submitError}</span>}
        </div>
      )}

      <div className="surface form-surface">
        <FormSection title="Basics and lifecycle" description="Core inventory classification and current operating status."
          disabled={submitting}>
          <div className="form-grid form-grid-three">
            <TextField {...fieldProps('frameId')} label="Frame ID" required={mode === 'create'} readOnly={mode === 'edit'} maxLength={64}
              help={mode === 'edit' ? 'Frame ID cannot be changed.' : undefined} />
            <TextField {...fieldProps('mediaType')} label="Media type" required placeholder="e.g. DIGITAL" />
            <TextField {...fieldProps('format')} label="Format" required placeholder="e.g. D6" />
            <TextField {...fieldProps('environment')} label="Environment" placeholder="e.g. UNDERGROUND" />
            <SelectField {...fieldProps('status')} label="Status" required>
              <option value="LIVE">LIVE</option>
              <option value="INACTIVE">INACTIVE</option>
            </SelectField>
            <TextField {...fieldProps('statusReason')} label="Status reason" wide multiline />
          </div>
        </FormSection>

        <FormSection title="Location" description="Postal address, geographic identifiers and coordinates."
          disabled={submitting}>
