import { useEffect, useRef, useState } from 'react'
import { createFrame, FrameApiError, getFrame, updateFrame } from '../api/frames'
import { FrameForm } from './FrameForm'
import {
  apiErrorsToForm,
  emptyFrameForm,
  frameToForm,
  toCreateRequest,
  toUpdateRequest,
  type FormErrors,
  type FrameFormValues,
} from './frameFormModel'

type Props = {
  mode: 'create' | 'edit'
  frameId?: string
  onCancel: () => void
  onSuccess: (frameId: string, mode: 'create' | 'edit') => void
}

export function FrameEditorPage({ mode, frameId, onCancel, onSuccess }: Props) {
  const headingRef = useRef<HTMLHeadingElement>(null)
  const [initialValues, setInitialValues] = useState<FrameFormValues | null>(mode === 'create' ? emptyFrameForm() : null)
  const [loadError, setLoadError] = useState<string | null>(null)
  const [loadAttempt, setLoadAttempt] = useState(0)
  const [submitting, setSubmitting] = useState(false)
  const [submitError, setSubmitError] = useState<string | null>(null)
  const [serverErrors, setServerErrors] = useState<FormErrors>({})

  useEffect(() => {
    headingRef.current?.focus()
  }, [])

  useEffect(() => {
    if (mode !== 'edit' || !frameId) return
    const controller = new AbortController()
    getFrame(frameId, controller.signal)
      .then((frame) => setInitialValues(frameToForm(frame)))
      .catch((caught: unknown) => {
        if (caught instanceof DOMException && caught.name === 'AbortError') return
        setLoadError(errorMessage(caught))
      })
    return () => controller.abort()
  }, [frameId, loadAttempt, mode])

  const submit = async (values: FrameFormValues) => {
    if (submitting) return
    setSubmitting(true)
    setSubmitError(null)
    setServerErrors({})
    try {
      const saved = mode === 'create'
        ? await createFrame(toCreateRequest(values))
        : await updateFrame(frameId!, toUpdateRequest(values))
      onSuccess(saved.frameId, mode)
    } catch (caught: unknown) {
      setSubmitError(errorMessage(caught))
      setServerErrors(caught instanceof FrameApiError ? apiErrorsToForm(caught.fieldErrors) : {})
      setSubmitting(false)
    }
  }

  const clearSubmitState = () => {
    if (submitError) setSubmitError(null)
    if (Object.keys(serverErrors).length > 0) setServerErrors({})
  }

  return (
    <>
      <header className="page-header editor-page-header">
        <button className="button back-button" type="button" disabled={submitting} onClick={onCancel} aria-label="Back to frames">
          <BackIcon />
        </button>
        <div>
          <h1 ref={headingRef} tabIndex={-1}>{mode === 'create' ? 'New frame' : 'Edit frame'}</h1>
          <p className="page-meta">
            {mode === 'create' ? 'Add a new physical OOH frame to the inventory.' : `Update inventory details for ${frameId}.`}
          </p>
        </div>
      </header>
      <div className="editor-layout">
        {initialValues ? (
          <FrameForm mode={mode} initialValues={initialValues} submitting={submitting}
            submitError={submitError} serverErrors={serverErrors} onSubmit={submit}
            onCancel={onCancel} onValueChange={clearSubmitState} />
        ) : loadError ? (
          <div className="surface"><div className="state-panel" role="alert"><div className="state-panel-content">
            <span className="state-icon"><AlertIcon /></span>
            <h2>Could not load frame</h2><p>{loadError}</p>
            <button className="button button-primary" type="button" onClick={() => {
              setLoadError(null)
              setInitialValues(null)
              setLoadAttempt((value) => value + 1)
            }}>
              Try again
            </button>
          </div></div></div>
        ) : (
          <div className="surface"><div className="state-panel" role="status"><div className="state-panel-content">
            <span className="state-icon"><span className="loading-spinner" /></span>
            <h2>Loading frame</h2><p>Fetching the latest inventory details.</p>
          </div></div></div>
        )}
      </div>
    </>
  )
}

function errorMessage(caught: unknown) {
  return caught instanceof FrameApiError || caught instanceof Error ? caught.message : 'An unexpected error occurred.'
}

function BackIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <path d="m15 18-6-6 6-6" />
  </svg>
}

function AlertIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <circle cx="12" cy="12" r="9" /><path d="M12 8v5M12 16h.01" />
  </svg>
}

type Props = {
  page: number; size: number; totalElements: number; totalPages: number; disabled: boolean
  onPageChange: (page: number) => void; onSizeChange: (size: number) => void
}

export function Pagination({ page, size, totalElements, totalPages, disabled, onPageChange, onSizeChange }: Props) {
  const start = totalElements === 0 ? 0 : page * size + 1
  const end = Math.min((page + 1) * size, totalElements)
  const displayedPage = totalPages === 0 ? 0 : page + 1

  return (
    <nav className="pagination" aria-label="Inventory pagination">
      <span>Showing {start}â€“{end} of {totalElements}</span><span className="pagination-spacer" />
      <label className="page-size">Rows per page
        <select className="select" value={size} disabled={disabled}
          onChange={(event) => onSizeChange(Number(event.target.value))}>
          <option value={20}>20</option><option value={50}>50</option><option value={100}>100</option>
        </select>
      </label>
      <div className="page-controls">
        <button className="button" type="button" disabled={disabled || page === 0}
          onClick={() => onPageChange(page - 1)}>Previous</button>
        <span className="page-indicator">Page {displayedPage} of {totalPages}</span>
        <button className="button" type="button"
          disabled={disabled || totalPages === 0 || page >= totalPages - 1}
          onClick={() => onPageChange(page + 1)}>Next</button>
      </div>
    </nav>
  )
}

import type { FrameSummary } from '../api/frames'

const dateFormatter = new Intl.DateTimeFormat(undefined, { dateStyle: 'medium', timeStyle: 'short' })

type Props = {
  frames: FrameSummary[]
  onView: (frameId: string) => void
  onEdit: (frameId: string) => void
}

export function FrameTable({ frames, onView, onEdit }: Props) {
  return (
    <div className="table-scroll" role="region" tabIndex={0} aria-label="Scrollable frame inventory table">
      <table className="inventory-table">
        <caption className="sr-only">Frame inventory search results</caption>
        <thead><tr>
          <th scope="col">Frame ID</th><th scope="col">Site</th><th scope="col">Location</th>
          <th scope="col">Media type</th><th scope="col">Format</th><th scope="col">Environment</th>
          <th scope="col">Status</th><th scope="col">Last updated</th><th scope="col"><span className="sr-only">Actions</span></th>
        </tr></thead>
        <tbody>{frames.map((frame) => (
          <tr key={frame.frameId}>
            <td><button className="frame-link frame-id" type="button" onClick={() => onView(frame.frameId)}>
              {frame.frameId}
            </button></td>
            <td><StackedValue primary={frame.station || frame.airport} secondary={frame.address} /></td>
            <td><StackedValue primary={frame.town} secondary={frame.region} /></td>
            <td>{displayValue(frame.mediaType)}</td><td>{displayValue(frame.format)}</td>
            <td>{displayValue(frame.environment)}</td><td><StatusChip status={frame.status} /></td>
            <td><time className="date-value" dateTime={frame.modifiedDate}>{formatDate(frame.modifiedDate)}</time></td>
            <td><button className="button table-edit-button" type="button" onClick={() => onEdit(frame.frameId)}
              aria-label={`Edit frame ${frame.frameId}`}><EditIcon /> Edit</button></td>
          </tr>
        ))}</tbody>
      </table>
    </div>
  )
}

function StackedValue({ primary, secondary }: { primary: string | null; secondary: string | null }) {
  return (
    <span className="stacked-value">
      <span title={primary || undefined}>{displayValue(primary)}</span>
      {secondary && <span className="secondary" title={secondary}>{secondary}</span>}
    </span>
  )
}

function StatusChip({ status }: { status: string }) {
  const normalized = status.toUpperCase()
  const statusClass = normalized === 'LIVE' ? 'status-live' : normalized === 'INACTIVE' ? 'status-inactive' : ''
  return <span className={`status-chip ${statusClass}`.trim()}>{status}</span>
}

function EditIcon() {
  return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true">
    <path d="M12 20h9" /><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z" />
  </svg>
}

function formatDate(value: string) {
  const date = new Date(value)
  return Number.isNaN(date.getTime()) ? 'â€”' : dateFormatter.format(date)
}

function displayValue(value: string | null) { return value || 'â€”' }

