import { render, screen, within } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { beforeEach, describe, expect, it, vi } from 'vitest'
import { importFrames } from '../api/frames'
import { CsvImportPage } from './CsvImportPage'

vi.mock('../api/frames', async (importOriginal) => {
  const actual = await importOriginal<typeof import('../api/frames')>()
  return { ...actual, importFrames: vi.fn() }
})

const mockedImportFrames = vi.mocked(importFrames)

describe('CsvImportPage', () => {
  beforeEach(() => mockedImportFrames.mockReset())

  it('renders a partial import summary and row-level errors', async () => {
    mockedImportFrames.mockResolvedValue({
      totalRows: 4,
      created: 2,
      duplicates: 1,
      failed: 1,
      errors: [
        { rowNumber: 3, frameId: 'FRAME-3', reason: 'Frame already exists' },
        { rowNumber: 4, frameId: null, reason: 'Frame ID is required' },
      ],
    })
    const user = userEvent.setup()
    render(<CsvImportPage onViewInventory={vi.fn()} />)
    const file = new File(['frame_id\nFRAME-1'], 'frames.csv', { type: 'text/csv' })

    await user.upload(screen.getByLabelText('CSV file'), file)
    await user.click(screen.getByRole('button', { name: 'Import CSV' }))

    expect(await screen.findByRole('heading', { name: 'Import partially successful' })).toBeInTheDocument()
    expect(screen.getByText('2 of 4 rows were imported.')).toBeInTheDocument()
    expect(within(screen.getByLabelText('Import summary')).getByText('2')).toBeInTheDocument()
    expect(screen.getByRole('heading', { name: 'Rows not imported' })).toBeInTheDocument()
    expect(screen.getByText('FRAME-3')).toBeInTheDocument()
    expect(screen.getByText('Frame already exists')).toBeInTheDocument()
    expect(mockedImportFrames).toHaveBeenCalledWith(file)
  })
})

import { render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { beforeEach, describe, expect, it, vi } from 'vitest'
import { getFrames, type FrameSummary } from '../api/frames'
import { InventoryPage } from './InventoryPage'

vi.mock('../api/frames', async (importOriginal) => {
  const actual = await importOriginal<typeof import('../api/frames')>()
  return { ...actual, getFrames: vi.fn() }
})

const FRAME: FrameSummary = {
  frameId: 'FRAME-1',
  mediaType: 'DIGITAL',
  format: 'D6',
  environment: 'UNDERGROUND',
  status: 'LIVE',
  modifiedDate: '2026-08-31T10:00:00Z',
  address: 'Platform 1',
  town: 'London',
  region: 'London',
  station: 'Central',
  airport: null,
}

const mockedGetFrames = vi.mocked(getFrames)

describe('InventoryPage', () => {
  beforeEach(() => {
    mockedGetFrames.mockReset()
    mockedGetFrames.mockImplementation(async (params) => ({
      items: [FRAME],
      page: params.page,
      size: params.size,
      totalElements: 40,
      totalPages: 2,
    }))
  })

  it('normalizes typed filters, resets pagination, and debounces trimmed searches', async () => {
    const user = userEvent.setup()
    render(
      <InventoryPage successMessage={null} focusOnMount={false} onNew={vi.fn()} onImport={vi.fn()}
        onView={vi.fn()} onEdit={vi.fn()} />,
    )

    await screen.findByRole('button', { name: 'FRAME-1' })
    expect(mockedGetFrames).toHaveBeenNthCalledWith(1, {
      status: '', mediaType: '', environment: '', format: '', region: '', page: 0, size: 20, q: '',
    }, expect.any(AbortSignal))

    await user.click(screen.getByRole('button', { name: 'Next' }))
    await waitFor(() => expect(mockedGetFrames.mock.calls.at(-1)?.[0].page).toBe(1))

    await user.type(screen.getByLabelText('Media type'), '  DIGITAL  ')
    await waitFor(() => expect(mockedGetFrames.mock.calls.at(-1)?.[0]).toMatchObject({
      mediaType: 'DIGITAL', page: 0,
    }))

    const callsBeforeSearchSettles = mockedGetFrames.mock.calls.length
    await user.type(screen.getByLabelText('Search'), '  London  ')
    expect(mockedGetFrames).toHaveBeenCalledTimes(callsBeforeSearchSettles)
    await waitFor(() => expect(mockedGetFrames.mock.calls.at(-1)?.[0]).toMatchObject({
      mediaType: 'DIGITAL', q: 'London', page: 0,
    }))
  })
})

import { afterEach, describe, expect, it, vi } from 'vitest'
import { getFrame, getFrames } from './frames'

describe('frame API', () => {
  afterEach(() => vi.unstubAllGlobals())

  it('builds a normalized inventory query and forwards the abort signal', async () => {
    const page = { items: [], page: 2, size: 50, totalElements: 0, totalPages: 0 }
    const fetchMock = vi.fn().mockResolvedValue(new Response(JSON.stringify(page), { status: 200 }))
    vi.stubGlobal('fetch', fetchMock)
    const controller = new AbortController()

    await getFrames({
      page: 2,
      size: 50,
      q: ' station ',
      status: 'LIVE',
      mediaType: ' DIGITAL ',
      environment: ' ',
      format: '',
      region: ' London ',
    }, controller.signal)

    expect(fetchMock).toHaveBeenCalledWith(
      '/api/frames?page=2&size=50&q=station&status=LIVE&mediaType=DIGITAL&region=London',
      { signal: controller.signal, headers: { Accept: 'application/json' } },
    )
  })

  it('maps problem details and malformed failures to safe API errors', async () => {
    const fetchMock = vi.fn()
      .mockResolvedValueOnce(new Response(JSON.stringify({
        detail: 'One or more fields are invalid',
        errors: [{ field: 'frameId', message: 'Frame ID is required.' }],
      }), { status: 400 }))
      .mockResolvedValueOnce(new Response('not-json', { status: 503 }))
    vi.stubGlobal('fetch', fetchMock)

    await expect(getFrame('unsafe/id')).rejects.toMatchObject({
      name: 'FrameApiError',
      status: 400,
      message: 'One or more fields are invalid',
      fieldErrors: [{ field: 'frameId', message: 'Frame ID is required.' }],
    })
    expect(fetchMock.mock.calls[0]?.[0]).toBe('/api/frames/unsafe%2Fid')

    await expect(getFrame('FRAME-2')).rejects.toMatchObject({
      name: 'FrameApiError', status: 503, message: 'Request failed with status 503', fieldErrors: [],
    })
  })
})

